findWordContaining(offset) {
        if (offset < 0 || offset >= this.b.length) {
            return undefined;
        }
        if (!isWordChar(this.b[offset])) {
            return undefined;
        }
        // find start
        let start = offset;
        while (start > 0 && isWordChar(this.b[start - 1])) {
            start--;
        }
        // find end
        let end = offset;
        while (end < this.b.length && isWordChar(this.b[end])) {
            end++;
        }
        return new $hD(start, end);
    }
